const E13_2_CE_TEXT = `Trouver un stage : nos conseils

Vous cherchez un stage pour la fin de vos études ? Ne perdez pas de temps : les stages commencent souvent au début de l'année, et les meilleures places partent vite.
Commencez par consulter les sites de recherche d'emploi. Sur notre site, vous pouvez consulter des offres de stages, d'emplois saisonniers ou de CDI. Créez votre profil et mettez votre CV en ligne : les employeurs peuvent le voir directement.
L'inscription est gratuite et prend dix minutes. Elle n'est pas obligatoire pour lire les annonces, mais elle est nécessaire pour répondre aux offres.
Vous n'avez personne pour vous aider ? Nos conseillers répondent à vos questions du lundi au vendredi, de 9 h à 17 h, par téléphone ou par messagerie. N'attendez pas trop pour déposer votre candidature !`;

