const E13_3_RECRUTEUR = { title: "Le recruteur", vous: "le recruteur / la recruteuse" };
const E13_3_CANDIDAT = { title: "Le candidat", vous: "le candidat / la candidate" };
const E13_3_AMI = { title: "L'ami", vous: "l'ami(e)" };
const E13_3_CONSEILLER = { title: "Le conseiller", vous: "le conseiller / la conseillère" };
const E13_3_RESPONSABLE = { title: "Le responsable du magasin", vous: "le / la responsable" };
