const E13_4_CE_TEXT = `Réussir son entretien d'embauche

Vous avez décroché un entretien ? Félicitations ! Voici nos conseils pour bien le préparer.
Tout d'abord, renseignez-vous sur l'entreprise : ses produits, ses équipes, ses valeurs. Ensuite, préparez votre présentation : votre parcours, vos diplômes et vos années d'expérience. Enfin, entraînez-vous à répondre aux questions classiques : « Parlez-moi de vous », « Quelles sont vos qualités et vos défauts ? »
Attention aux questions pièges ! Restez calme et donnez des exemples concrets. Pour les défauts, choisissez-en un et expliquez comment vous progressez : « Je suis parfois perfectionniste, mais j'apprends à aller plus vite. »
Le jour de l'entretien, arrivez dix minutes en avance, habillez-vous simplement et n'oubliez pas votre CV. À la fin, vous pouvez poser des questions sur le poste : le contrat, les horaires et les congés payés.`;

