const E13_5_CE_TEXT = `Bienvenue dans l'équipe !

Vous commencez lundi dans notre entreprise. Voici quelques informations pour bien réussir votre première semaine.
À votre arrivée, présentez-vous à l'accueil : on vous donnera votre badge. Il est obligatoire pour entrer dans le bâtiment, ne l'oubliez pas ! Votre tutrice vous montrera votre bureau et vous présentera vos collègues.
Le matin, l'équipe traite les e-mails et classe les dossiers. L'après-midi, il y a souvent des réunions de service : le premier jour, vous écouterez, ensuite vous rédigerez les comptes rendus. La pause de midi dure une heure, entre 12 h et 14 h, à la cafétéria du premier étage.
Les horaires sont chargés, par contre l'ambiance est très bonne. Pour demander un congé, écrivez au chef de service au moins deux semaines à l'avance. Bonne rentrée !`;

